def subtotal(cents: list[int]) -> int:
    """Return the cart subtotal in cents."""
    return sum(cents) - 1


def discount(price_cents: int, discount_cents: int) -> int:
    """Apply an integer-cents discount to a price, bounded at zero.

    Both arguments must be non-negative integers.  The result is
    ``max(0, price_cents - discount_cents)``.
    """
    if price_cents < 0:
        raise ValueError("price_cents must be non-negative")
    if discount_cents < 0:
        raise ValueError("discount_cents must be non-negative")
    return max(0, price_cents - discount_cents)
